sections.body:
将下列代码保存为 migration.mjs，用 node migration.mjs 运行，无额外依赖。函数接收 JSON 文本；示例的安全整数上限用于防止 JavaScript 数值精度丢失，不是游戏经济上限。

```javascript
/**
 * @file Migrate an original tutorial save without touching storage.
 * @author liliwei
 * @date 2026-11-18
 * @LastEditors liliwei
 * @LastEditTime 2026-11-18
 */

/** @param {object} value Parsed JSON object. @param {string[]} keys Exact fields. @returns {void} */
function fields(value, keys) {
  if (!value || typeof value !== 'object' || Array.isArray(value) ||
      Object.keys(value).length !== keys.length ||
      !keys.every(key => Object.hasOwn(value, key))) {
    throw new Error('Unexpected fields');
  }
}

/** @param {number} value Stored integer. @param {number} min Lower bound. @param {number} max Upper bound. @returns {number} */
function integer(value, min, max) {
  if (!Number.isSafeInteger(value) || value < min || value > max) {
    throw new Error('Invalid integer');
  }
  return value;
}

/** @param {string} raw Original JSON text. @returns {object} Validated v2 save; never writes storage. */
export function migrate(raw) {
  if (typeof raw !== 'string') throw new Error('Expected JSON text');
  const save = JSON.parse(raw);
  if (save?.schemaVersion === 1) {
    fields(save, ['schemaVersion', 'coins', 'nextLevel']);
    const gold = integer(save.coins, 0, Number.MAX_SAFE_INTEGER);
    const clearedThrough = integer(save.nextLevel, 1, 101) - 1;
    return { schemaVersion: 2, wallet: { gold }, progress: { clearedThrough } };
  }
  if (save?.schemaVersion === 2) {
    fields(save, ['schemaVersion', 'wallet', 'progress']);
    fields(save.wallet, ['gold']);
    fields(save.progress, ['clearedThrough']);
    const gold = integer(save.wallet.gold, 0, Number.MAX_SAFE_INTEGER);
    const clearedThrough = integer(save.progress.clearedThrough, 0, 100);
    return { schemaVersion: 2, wallet: { gold }, progress: { clearedThrough } };
  }
  throw new Error('Unsupported schema version');
}

const old = '{"schemaVersion":1,"coins":0,"nextLevel":8}';
const upgraded = migrate(old);
console.log(JSON.stringify(upgraded));
console.log('idempotent:', JSON.stringify(migrate(JSON.stringify(upgraded))) === JSON.stringify(upgraded));
```

代码只接受本期的两种完整格式。fields 检查形状，integer 检查范围，映射负责业务含义；三者不能互相替代。不要用 coins || 100 填余额，因为合法的 0 会被覆盖。也不要直接令 clearedThrough=nextLevel，字段类型虽仍正确，却多送了一关进度。

这里的 JSON 是应用自己按约定序列化的普通存档。若入口接受任意外部文件，还要在解析前限制大小，并按导入需求处理重复 JSON 键等问题；这段代码不是通用存档修复器。
